-- ---------------------------------------------------------------- full-text search
-- English rows use the `english` config; Hindi rows use `simple`.
create or replace function public.items_fts_refresh() returns trigger
language plpgsql as $$
declare
  cfg regconfig := case when new.language = 'hi' then 'simple'::regconfig else 'english'::regconfig end;
begin
  new.fts :=
    setweight(to_tsvector(cfg, coalesce(new.title, '')), 'A') ||
    setweight(to_tsvector(cfg, coalesce(array_to_string(new.tags, ' '), '') || ' ' ||
                               coalesce(array_to_string(new.discipline, ' '), '')), 'B') ||
    setweight(to_tsvector(cfg, coalesce(new.description, '')), 'C') ||
    setweight(to_tsvector('simple'::regconfig, coalesce(array_to_string(new.authors, ' '), '')), 'D');
  return new;
end $$;
create trigger t_items_fts before insert or update on public.items
  for each row execute function public.items_fts_refresh();

create or replace function public.chunks_fts_refresh() returns trigger
language plpgsql as $$
declare
  item_lang public.lang;
begin
  select language into item_lang from public.items where id = new.item_id;
  new.fts := to_tsvector(case when item_lang = 'hi' then 'simple'::regconfig else 'english'::regconfig end,
                         coalesce(new.content, ''));
  return new;
end $$;
create trigger t_chunks_fts before insert or update of content on public.chunks
  for each row execute function public.chunks_fts_refresh();

create index items_fts_idx on public.items using gin (fts);
create index chunks_fts_idx on public.chunks using gin (fts);
create index chunks_embedding_idx on public.chunks using hnsw (embedding extensions.vector_cosine_ops);
create index items_expedition_idx on public.items (expedition_id);
create index items_type_status_idx on public.items (type, status, visibility);
create index chunks_item_idx on public.chunks (item_id);
create index generation_claims_gen_idx on public.generation_claims (generation_id);
create index search_events_at_idx on public.search_events (at);
create index item_views_item_idx on public.item_views (item_id);

-- ---------------------------------------------------------------- role helpers
-- Named app_current_role() because CURRENT_ROLE is a reserved SQL keyword.
create or replace function public.app_current_role() returns public.app_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;

create or replace function public.current_org() returns uuid
language sql stable security definer set search_path = public as $$
  select org_id from public.profiles where id = auth.uid()
$$;

create or replace function public.is_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_current_role() in ('curator', 'reviewer', 'admin'), false)
$$;

create or replace function public.is_reviewer() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_current_role() in ('reviewer', 'admin'), false)
$$;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_current_role() = 'admin', false)
$$;

-- The public-release rule, in one place.
create or replace function public.item_is_public(i public.items) returns boolean
language sql stable as $$
  select i.status = 'published' and i.visibility = 'public'
         and (i.embargo_until is null or i.embargo_until <= now())
$$;

create or replace function public.item_id_is_public(p_item_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.items i
    where i.id = p_item_id and i.status = 'published' and i.visibility = 'public'
      and (i.embargo_until is null or i.embargo_until <= now())
  )
$$;

create or replace function public.item_id_in_my_org(p_item_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_staff() and exists (
    select 1 from public.items i where i.id = p_item_id and i.org_id = public.current_org()
  )
$$;

-- ---------------------------------------------------------------- new-user trigger
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  staff record;
  default_org uuid;
begin
  select id into default_org from public.organizations where slug = 'ncpor' limit 1;
  select role, org_id into staff from public.allowed_staff where lower(email) = lower(new.email) limit 1;
  insert into public.profiles (id, full_name, email, avatar_url, role, org_id)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.email,
    new.raw_user_meta_data ->> 'avatar_url',
    coalesce(staff.role, 'member'),
    coalesce(staff.org_id, default_org)
  )
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- When an admin adds/changes an allow-list entry, apply it to an existing profile.
create or replace function public.sync_allowed_staff() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.profiles set role = new.role, org_id = coalesce(new.org_id, org_id)
  where lower(email) = lower(new.email);
  return new;
end $$;
create trigger t_allowed_staff_sync after insert or update on public.allowed_staff
  for each row execute function public.sync_allowed_staff();

-- Users may edit their own profile but never their own role.
-- SECURITY INVOKER on purpose: current_user must be the caller's role
-- (authenticated), not the function owner.
create or replace function public.guard_profile_role() returns trigger
language plpgsql security invoker set search_path = public as $$
begin
  if new.role is distinct from old.role
     and not public.is_admin()
     and coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     and current_user not in ('postgres', 'supabase_admin')
     and pg_trigger_depth() <= 1 then
    raise exception 'Only admins can change roles';
  end if;
  return new;
end $$;
create trigger t_profiles_guard_role before update on public.profiles
  for each row execute function public.guard_profile_role();

-- Approval gate: a generation with unsupported claims or unmatched numbers
-- cannot move to approved/published. This is the database-level guard.
create or replace function public.guard_generation_approval() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status in ('approved', 'published') and old.status is distinct from new.status then
    if exists (
      select 1 from public.generation_claims c
      where c.generation_id = new.id
        and (c.verdict = 'unsupported' or cardinality(c.number_misses) > 0)
    ) then
      raise exception 'Generation has unsupported claims or unmatched numbers';
    end if;
  end if;
  return new;
end $$;
create trigger t_generations_guard before update on public.generations
  for each row execute function public.guard_generation_approval();

-- ---------------------------------------------------------------- hybrid search
-- Keyword (FTS) + semantic (pgvector) with reciprocal rank fusion, grouped by
-- item. SECURITY INVOKER so RLS decides what each caller can see.
create or replace function public.search_items(
  query_text text,
  query_embedding extensions.vector(768) default null,
  filter_types public.item_type[] default null,
  filter_expedition uuid default null,
  filter_station uuid default null,
  filter_year int default null,
  filter_discipline text default null,
  filter_language public.lang default null,
  match_count int default 24,
  rrf_k int default 50
)
returns table (item_id uuid, snippet text, score double precision)
language sql stable security invoker set search_path = public, extensions as $$
  with q as (
    select websearch_to_tsquery('english', query_text) || websearch_to_tsquery('simple', query_text) as tsq
  ),
  candidates as (
    select i.* from public.items i
    where (filter_types is null or i.type = any (filter_types))
      and (filter_expedition is null or i.expedition_id = filter_expedition)
      and (filter_station is null or i.station_id = filter_station)
      and (filter_year is null or extract(year from i.event_date) = filter_year)
      and (filter_discipline is null or filter_discipline = any (i.discipline))
      and (filter_language is null or i.language = filter_language)
  ),
  kw_items as (
    select c.id as item_id, null::text as content,
           row_number() over (order by ts_rank_cd(c.fts, q.tsq) desc) as rank_ix
    from candidates c, q
    where c.fts @@ q.tsq
    order by rank_ix
    limit match_count * 2
  ),
  kw_chunks as (
    select ch.item_id, ch.content,
           row_number() over (order by ts_rank_cd(ch.fts, q.tsq) desc) as rank_ix
    from public.chunks ch join candidates c on c.id = ch.item_id, q
    where ch.fts @@ q.tsq
    order by rank_ix
    limit match_count * 4
  ),
  sem_chunks as (
    select ch.item_id, ch.content,
           row_number() over (order by ch.embedding <=> query_embedding) as rank_ix
    from public.chunks ch join candidates c on c.id = ch.item_id
    where query_embedding is not null and ch.embedding is not null
    order by rank_ix
    limit match_count * 4
  ),
  all_hits as (
    select * from kw_items union all select * from kw_chunks union all select * from sem_chunks
  ),
  fused as (
    select item_id, sum(1.0 / (rrf_k + rank_ix))::double precision as score
    from all_hits group by item_id
  ),
  best as (
    select distinct on (item_id) item_id, content
    from all_hits where content is not null
    order by item_id, rank_ix
  )
  select f.item_id, coalesce(left(b.content, 300), left(c.description, 300)) as snippet, f.score
  from fused f
  join candidates c on c.id = f.item_id
  left join best b on b.item_id = f.item_id
  order by f.score desc
  limit match_count
$$;

-- Semantic retrieval scoped to specific items (Studio, Ask NCPOR).
create or replace function public.match_chunks(
  query_embedding extensions.vector(768),
  item_ids uuid[] default null,
  match_count int default 8
)
returns table (id uuid, item_id uuid, page_no int, content text, similarity double precision)
language sql stable security invoker set search_path = public, extensions as $$
  select ch.id, ch.item_id, ch.page_no, ch.content, 1 - (ch.embedding <=> query_embedding) as similarity
  from public.chunks ch
  where ch.embedding is not null and (item_ids is null or ch.item_id = any (item_ids))
  order by ch.embedding <=> query_embedding
  limit match_count
$$;

-- ============================================================ 0002_rls.sql
-- Row Level Security: the real guard. Every table has RLS enabled.

alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.allowed_staff enable row level security;
alter table public.stations enable row level security;
alter table public.expeditions enable row level security;
alter table public.items enable row level security;
alter table public.item_files enable row level security;
alter table public.chunks enable row level security;
alter table public.dataset_profiles enable row level security;
alter table public.explainers enable row level security;
alter table public.generations enable row level security;
alter table public.generation_claims enable row level security;
alter table public.review_comments enable row level security;
alter table public.content_calendar enable row level security;
alter table public.glossary enable row level security;
alter table public.search_events enable row level security;
alter table public.item_views enable row level security;
alter table public.favourites enable row level security;
alter table public.quiz_attempts enable row level security;
alter table public.jobs enable row level security;
alter table public.audit_log enable row level security;

-- ---------------------------------------------------------------- public reference data
create policy "orgs: public read" on public.organizations for select using (true);
create policy "orgs: admin write" on public.organizations for all using (public.is_admin()) with check (public.is_admin());

create policy "stations: public read" on public.stations for select using (true);
create policy "stations: staff write" on public.stations for all using (public.is_staff()) with check (public.is_staff());

create policy "expeditions: public read" on public.expeditions for select using (true);
create policy "expeditions: staff write" on public.expeditions for all
  using (public.is_staff() and org_id = public.current_org())
  with check (public.is_staff() and org_id = public.current_org());

create policy "glossary: public read" on public.glossary for select using (true);
create policy "glossary: staff write" on public.glossary for all using (public.is_staff()) with check (public.is_staff());

create policy "calendar: public read" on public.content_calendar for select using (true);
create policy "calendar: staff write" on public.content_calendar for all using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- profiles & staff
create policy "profiles: read own" on public.profiles for select using (id = auth.uid() or public.is_staff());
create policy "profiles: update own" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "profiles: admin manage" on public.profiles for all using (public.is_admin()) with check (public.is_admin());

create policy "allowed_staff: admin only" on public.allowed_staff for all using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- items
create policy "items: public read released" on public.items for select
  using (status = 'published' and visibility = 'public' and (embargo_until is null or embargo_until <= now()));
create policy "items: staff read org" on public.items for select
  using (public.is_staff() and org_id = public.current_org());
create policy "items: staff insert" on public.items for insert
  with check (public.is_staff() and org_id = public.current_org() and (status <> 'published' or public.is_reviewer()));
create policy "items: staff update" on public.items for update
  using (public.is_staff() and org_id = public.current_org())
  with check (public.is_staff() and org_id = public.current_org() and (status <> 'published' or public.is_reviewer()));
create policy "items: reviewer delete" on public.items for delete
  using (public.is_reviewer() and org_id = public.current_org());

-- Children of items: readable when the parent is publicly released, or by staff of the org.
create policy "item_files: read" on public.item_files for select
  using (public.item_id_is_public(item_id) or public.item_id_in_my_org(item_id));
create policy "item_files: staff write" on public.item_files for all
  using (public.item_id_in_my_org(item_id)) with check (public.item_id_in_my_org(item_id));

create policy "chunks: read" on public.chunks for select
  using (public.item_id_is_public(item_id) or public.item_id_in_my_org(item_id));
create policy "chunks: staff write" on public.chunks for all
  using (public.item_id_in_my_org(item_id)) with check (public.item_id_in_my_org(item_id));

create policy "dataset_profiles: read" on public.dataset_profiles for select
  using (public.item_id_is_public(item_id) or public.item_id_in_my_org(item_id));
create policy "dataset_profiles: staff write" on public.dataset_profiles for all
  using (public.item_id_in_my_org(item_id)) with check (public.item_id_in_my_org(item_id));

create policy "explainers: read" on public.explainers for select
  using (public.item_id_is_public(item_id) or public.item_id_in_my_org(item_id));
-- Explainers are generated server-side on demand for public items only; written via the server.
create policy "explainers: staff write" on public.explainers for all
  using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- generations (Studio)
create policy "generations: public read published articles" on public.generations for select
  using (status = 'published' and channel = 'website_article');
create policy "generations: staff read" on public.generations for select
  using (public.is_staff() and org_id = public.current_org());
create policy "generations: staff insert" on public.generations for insert
  with check (public.is_staff() and org_id = public.current_org() and status in ('draft', 'in_review'));
-- Only reviewers approve/publish, and never their own work (admins may).
create policy "generations: staff update" on public.generations for update
  using (public.is_staff() and org_id = public.current_org())
  with check (
    public.is_staff() and org_id = public.current_org()
    and (
      status in ('draft', 'in_review')
      or (public.is_reviewer() and (created_by is distinct from auth.uid() or public.is_admin()))
    )
  );
create policy "generations: admin delete" on public.generations for delete using (public.is_admin());

create policy "claims: staff" on public.generation_claims for all using (public.is_staff()) with check (public.is_staff());
create policy "review_comments: staff" on public.review_comments for all using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- analytics (no personal data)
create policy "search_events: anyone insert" on public.search_events for insert with check (true);
create policy "search_events: staff read" on public.search_events for select using (public.is_staff());
create policy "item_views: anyone insert" on public.item_views for insert
  with check (public.item_id_is_public(item_id) or public.item_id_in_my_org(item_id));
create policy "item_views: staff read" on public.item_views for select using (public.is_staff());

-- ---------------------------------------------------------------- member features
create policy "favourites: owner" on public.favourites for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "quiz_attempts: owner" on public.quiz_attempts for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------- operations
create policy "jobs: staff" on public.jobs for all using (public.is_staff()) with check (public.is_staff());
create policy "audit: staff read" on public.audit_log for select using (public.is_staff());
create policy "audit: staff insert" on public.audit_log for insert with check (public.is_staff() and actor_id = auth.uid());

-- ---------------------------------------------------------------- grants for the API roles
grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;
grant insert, update, delete on all tables in schema public to authenticated;
grant insert on public.search_events, public.item_views to anon;
grant execute on all functions in schema public to anon, authenticated;

-- ============================================================ 0003_storage.sql
-- Storage buckets and policies.
--   public-media     approved photos, thumbnails and PDFs (public read; staff write)
--   private-uploads  drafts and embargoed files (staff only; signed URLs)
--   datasets         raw CSVs (staff write; read through signed URLs issued by the server)

insert into storage.buckets (id, name, public)
values ('public-media', 'public-media', true),
       ('private-uploads', 'private-uploads', false),
       ('datasets', 'datasets', false)
on conflict (id) do nothing;

create policy "public-media: public read" on storage.objects for select
  using (bucket_id = 'public-media');
create policy "public-media: staff write" on storage.objects for insert
  with check (bucket_id = 'public-media' and public.is_staff());
create policy "public-media: staff update" on storage.objects for update
  using (bucket_id = 'public-media' and public.is_staff());
create policy "public-media: staff delete" on storage.objects for delete
  using (bucket_id = 'public-media' and public.is_staff());

create policy "private-uploads: staff all" on storage.objects for all
  using (bucket_id = 'private-uploads' and public.is_staff())
  with check (bucket_id = 'private-uploads' and public.is_staff());

create policy "datasets: staff all" on storage.objects for all
  using (bucket_id = 'datasets' and public.is_staff())
  with check (bucket_id = 'datasets' and public.is_staff());

-- Realtime: live Review Queue badge and activity feed.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.generations, public.audit_log;
  end if;
end $$;

