insert into public.items (id, org_id, type, title, description, expedition_id, station_id, discipline, tags, authors, event_date, language, license, source_url, external_url, media_url, alt_text, status, visibility, embargo_until, is_sample, created_at) values ('00000000-0000-4000-a000-000000000155', '00000000-0000-4000-a000-000000000001', 'activity', '46-ISEA webpage advertisement (PDF) — external link', 'External link to NCPOR''s advertisement document for the 46th Indian Scientific Expedition to Antarctica. Hosted by NCPOR; linked and credited only.', '00000000-0000-4000-a000-000000000032', null, array['Programme']::text[], array['46-ISEA','announcement']::text[], array['NCPOR']::text[], null, 'en', 'See source site', 'http://isea.ncpor.res.in/forms/46-ISEA%20Webpage%20Advertisment.pdf', 'http://isea.ncpor.res.in/forms/46-ISEA%20Webpage%20Advertisment.pdf', null, null, 'published', 'public', null, false, '2026-01-05T09:00:00.000Z') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011011', '00000000-0000-4000-a000-000000000101', 1, 0, 'SAMPLE - not real data. 45-ISEA Summer Field Log. This fictional log demonstrates how an expedition report is archived. The summer field team worked from Maitri between 8 January 2026 and 21 January 2026. Daily planning meetings were held at 0800 hours and all field parties carried satellite messengers.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011012', '00000000-0000-4000-a000-000000000101', 2, 1, 'SAMPLE - not real data. Weather-station servicing. The team serviced 6 automatic weather stations along the coastal traverse. Batteries were replaced at 4 stations and one wind sensor was recalibrated. Recorded air temperature during the servicing period ranged from -12.4 °C to 2.1 °C.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011013', '00000000-0000-4000-a000-000000000101', 3, 2, 'SAMPLE - not real data. Snow and sea-ice observations. The team dug 12 snow pits and recorded density every 10 cm. Fast ice near the landing site was observed to break up in the final week of the campaign. Photographs and field sheets were uploaded to the internal archive for review.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011021', '00000000-0000-4000-a000-000000000102', 1, 0, 'SAMPLE - not real data. Glacier Mass-Balance Field Notes. This fictional note describes a glacier field season near Himansh from 1 September 2025 to 5 October 2025. The team re-measured a network of 34 ablation stakes on the glacier tongue.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011022', '00000000-0000-4000-a000-000000000102', 2, 1, 'SAMPLE - not real data. Snow density was measured at 3 accumulation-zone pits above 4,850 m. Debris cover on the lower tongue made several stakes hard to reach. The field team recommends replacing 5 stakes next season.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011031', '00000000-0000-4000-a000-000000000103', 1, 0, 'SAMPLE - not real data. Himadri Summer Campaign Overview. This fictional overview covers an 18-day campaign at Ny-Ålesund in June and July 2025. The team completed 3 fjord transects by small boat and logged weather observations twice daily.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011032', '00000000-0000-4000-a000-000000000103', 2, 1, 'SAMPLE - not real data. Outreach during the campaign included 2 live video calls with schools in India. Water samples were stored at 4 °C before shipment. All data sheets were digitised at the end of each week.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011041', '00000000-0000-4000-a000-000000000104', 1, 0, 'SAMPLE - not real data. Southern Ocean Transect Cruise Summary. This fictional summary describes a ship-based transect from 20 December 2024 to 10 February 2025. The science team completed 42 CTD casts measuring temperature, salinity and depth.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011042', '00000000-0000-4000-a000-000000000104', 2, 1, 'SAMPLE - not real data. Plankton nets were deployed at 15 stations and krill were observed in several net hauls. Rough sea states on 6 days delayed deck operations. Samples were preserved for later laboratory analysis.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011051', '00000000-0000-4000-a000-000000000105', 1, 0, 'SAMPLE - internal. Station logistics debrief: fuel handling, generator maintenance schedule and cargo notes. This item is internal and must never be sent to an AI service.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011061', '00000000-0000-4000-a000-000000000106', 1, 0, 'SAMPLE - embargoed. Preliminary snow chemistry results pending peer review. This item is embargoed and must not appear publicly or be sent to an AI service before its release date.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011211', '00000000-0000-4000-a000-000000000121', 1, 0, 'SAMPLE abstract - not a real publication. We describe snow-pit stratigraphy from 12 pits dug at a coastal Antarctic site during a summer field season. Density was recorded every 10 cm. Layers of wind-packed snow alternated with softer layers. The sample shows how abstracts are stored, cited and explained at three levels.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011221', '00000000-0000-4000-a000-000000000122', 1, 0, 'SAMPLE abstract - not a real publication. Debris-covered glaciers are common in the Himalaya. In this fictional study, stake readings from 34 stakes were compared between clean ice and debris-covered ice. The sample is used to demonstrate the Content Studio and Trust Panel.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011231', '00000000-0000-4000-a000-000000000123', 1, 0, 'नमूना सार - वास्तविक प्रकाशन नहीं। इस काल्पनिक अध्ययन में आर्कटिक फ्योर्ड में 3 अनुप्रस्थ मार्गों पर जल तापमान दर्ज किया गया। नमूने 4 °C पर रखे गए। यह सार दिखाता है कि हिंदी सामग्री कैसे खोजी और समझाई जाती है।') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011411', '00000000-0000-4000-a000-000000000141', 1, 0, 'SAMPLE transcript. Good morning from the station. Our day starts with a weather briefing, then field teams check their radios and set out. In the evening everyone shares what they observed. This is a placeholder transcript for a demo video.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011421', '00000000-0000-4000-a000-000000000142', 1, 0, 'SAMPLE transcript. An ice core is drilled using a hollow drill that cuts a cylinder of ice. Each section is lifted, logged and packed in insulated boxes. This is a placeholder transcript for a demo video.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011431', '00000000-0000-4000-a000-000000000143', 1, 0, 'SAMPLE transcript. A weather balloon carries a small instrument package called a radiosonde. It sends back temperature, humidity and wind readings as it rises. This is a placeholder transcript for a demo video.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011511', '00000000-0000-4000-a000-000000000151', 1, 0, 'SAMPLE activity record. Polar Science Week included talks for school students, a hands-on ice demonstration and a short quiz. 120 students took part in this fictional sample event.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011521', '00000000-0000-4000-a000-000000000152', 1, 0, 'SAMPLE activity record. A one-day teacher workshop introduced the cryosphere, polar stations and classroom activities. 30 teachers received a sample teacher pack.') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011531', '00000000-0000-4000-a000-000000000153', 1, 0, 'नमूना गतिविधि रिकॉर्ड। हिंदी पखवाड़े के दौरान छात्रों के लिए ध्रुवीय विज्ञान प्रश्नोत्तरी आयोजित की गई। इस काल्पनिक कार्यक्रम में 80 छात्रों ने भाग लिया।') on conflict do nothing;
insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011311', '00000000-0000-4000-a000-000000000131', 1, 0, 'Illustration caption: aurora bands above a coastal station. Sample illustration, not a photograph.') on conflict do nothing;
