insert into public.dataset_profiles (item_id, columns, row_count, time_range, units, stats, summary, sample_rows) values ('00000000-0000-4000-a000-000000000112', '[{"name":"month","kind":"date","count":72,"missing":0,"missingPct":0,"unit":null,"min":"2020-01","max":"2025-12"},{"name":"sea_ice_index","kind":"number","count":72,"missing":0,"missingPct":0,"unit":"index (unitless)","min":13.75,"max":87.27,"mean":49.54},{"name":"anomaly_index","kind":"number","count":72,"missing":0,"missingPct":0,"unit":"index (unitless)","min":-2,"max":1.99,"mean":-0.17}]'::jsonb, 72, '{"column":"month","start":"2020-01","end":"2025-12"}'::jsonb, '{"sea_ice_index":"index (unitless)","anomaly_index":"index (unitless)"}'::jsonb, '{"parse_errors":0}'::jsonb, null, '[{"month":"2020-01","sea_ice_index":"29.61","anomaly_index":"0.00"},{"month":"2020-02","sea_ice_index":"22.27","anomaly_index":"-0.24"},{"month":"2020-03","sea_ice_index":"15.88","anomaly_index":"1.99"},{"month":"2020-04","sea_ice_index":"16.92","anomaly_index":"-0.92"},{"month":"2020-05","sea_ice_index":"30.17","anomaly_index":"0.51"}]'::jsonb) on conflict (item_id) do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000900', 'cryosphere', 'हिममंडल', 'All the frozen water on Earth: snow, sea ice, glaciers, ice sheets and frozen ground.', 'पृथ्वी पर जमा हुआ सारा पानी: बर्फ, समुद्री बर्फ, हिमनद, हिम चादरें और जमी हुई ज़मीन।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000901', 'ice core', 'हिम कोर', 'A long cylinder of ice drilled out of a glacier or ice sheet. Its layers hold clues about past climate.', 'हिमनद या हिम चादर से ड्रिल करके निकाला गया बर्फ का लंबा बेलन। इसकी परतों में पुराने जलवायु के सुराग होते हैं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000902', 'katabatic wind', 'कैटाबेटिक पवन', 'Cold, heavy air that flows downhill off high ice, often very strongly.', 'ऊँची बर्फ से ढलान पर नीचे बहने वाली ठंडी, भारी हवा, जो अक्सर बहुत तेज़ होती है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000903', 'polynya', 'पॉलिन्या', 'An area of open water surrounded by sea ice.', 'समुद्री बर्फ से घिरा खुले पानी का क्षेत्र।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000904', 'ice shelf', 'हिम शेल्फ', 'A thick floating platform of ice where an ice sheet flows from land onto the ocean.', 'बर्फ का मोटा तैरता मंच, जहाँ हिम चादर ज़मीन से समुद्र पर बहती है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000905', 'permafrost', 'पर्माफ्रॉस्ट', 'Ground that stays frozen for at least two years in a row.', 'ऐसी ज़मीन जो लगातार कम से कम दो साल तक जमी रहती है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000906', 'krill', 'क्रिल', 'Small shrimp-like animals in the ocean that many whales, seals and penguins eat.', 'समुद्र में रहने वाले छोटे झींगे जैसे जीव, जिन्हें कई व्हेल, सील और पेंगुइन खाते हैं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000907', 'Southern Ocean', 'दक्षिणी महासागर', 'The ocean that surrounds Antarctica.', 'अंटार्कटिका को घेरने वाला महासागर।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000908', 'sea ice', 'समुद्री बर्फ', 'Ice that forms when ocean water freezes.', 'समुद्र का पानी जमने से बनी बर्फ।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000909', 'glacier', 'हिमनद', 'A large, slow-moving mass of ice formed from snow that builds up over many years.', 'कई वर्षों में जमा हुई बर्फ से बना, धीरे-धीरे खिसकने वाला बर्फ का बड़ा पिंड।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000910', 'ice sheet', 'हिम चादर', 'A huge layer of glacial ice covering land, like those on Antarctica and Greenland.', 'ज़मीन को ढकने वाली हिमनदी बर्फ की विशाल परत, जैसे अंटार्कटिका और ग्रीनलैंड पर।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000911', 'iceberg', 'हिमखंड', 'A large piece of freshwater ice that has broken off a glacier or ice shelf and floats in the sea.', 'हिमनद या हिम शेल्फ से टूटकर समुद्र में तैरता मीठे पानी की बर्फ का बड़ा टुकड़ा।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000912', 'calving', 'काल्विंग', 'When chunks of ice break off the edge of a glacier or ice shelf.', 'जब हिमनद या हिम शेल्फ के किनारे से बर्फ के टुकड़े टूटकर गिरते हैं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000913', 'albedo', 'एल्बिडो', 'How much sunlight a surface reflects. Fresh snow reflects a lot; dark ocean reflects little.', 'कोई सतह कितनी धूप परावर्तित करती है। ताज़ी बर्फ बहुत, और गहरा समुद्र कम परावर्तित करता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000914', 'aurora', 'ध्रुवीय ज्योति', 'Glowing lights in the night sky near the poles, caused by charged particles from the Sun.', 'ध्रुवों के पास रात के आकाश में चमकती रोशनी, जो सूर्य से आए आवेशित कणों से बनती है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000915', 'polar night', 'ध्रुवीय रात', 'A period in polar winter when the Sun stays below the horizon all day.', 'ध्रुवीय सर्दियों का वह समय जब सूर्य पूरे दिन क्षितिज के नीचे रहता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000916', 'midnight sun', 'मध्यरात्रि सूर्य', 'A period in polar summer when the Sun stays above the horizon all day and night.', 'ध्रुवीय गर्मियों का वह समय जब सूर्य दिन-रात क्षितिज के ऊपर रहता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000917', 'blizzard', 'बर्फ़ीला तूफ़ान', 'A severe snowstorm with strong winds and very low visibility.', 'तेज़ हवाओं और बहुत कम दृश्यता वाला भीषण बर्फ़ीला तूफ़ान।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000918', 'crevasse', 'दरार', 'A deep crack in a glacier or ice sheet.', 'हिमनद या हिम चादर में गहरी दरार।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000919', 'moraine', 'हिमोढ़', 'Rocks and soil carried and left behind by a glacier.', 'हिमनद द्वारा बहाकर लाई और छोड़ी गई चट्टानें और मिट्टी।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000920', 'fast ice', 'स्थिर बर्फ', 'Sea ice that is attached to the coast or the sea floor and does not drift.', 'समुद्री बर्फ जो तट या समुद्र तल से जुड़ी रहती है और बहती नहीं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000921', 'pack ice', 'पैक बर्फ', 'Sea ice that floats freely and moves with winds and currents.', 'समुद्री बर्फ जो स्वतंत्र रूप से तैरती है और हवा व धाराओं के साथ चलती है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000922', 'ozone hole', 'ओज़ोन छिद्र', 'A seasonal thinning of the ozone layer, observed over Antarctica.', 'ओज़ोन परत का मौसमी पतलापन, जो अंटार्कटिका के ऊपर देखा जाता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000923', 'phytoplankton', 'पादप प्लवक', 'Tiny plant-like organisms drifting in the ocean that make food using sunlight.', 'समुद्र में बहने वाले सूक्ष्म पौधे जैसे जीव, जो धूप से भोजन बनाते हैं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000924', 'automatic weather station', 'स्वचालित मौसम केंद्र', 'An instrument station that records weather such as temperature and wind without a person present.', 'एक उपकरण केंद्र जो बिना किसी व्यक्ति के तापमान और हवा जैसे मौसम को दर्ज करता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000925', 'ice-core drilling', 'हिम कोर ड्रिलिंग', 'Using a special drill to extract ice cores for study.', 'अध्ययन के लिए विशेष ड्रिल से हिम कोर निकालना।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000926', 'research station', 'अनुसंधान केंद्र', 'A base where scientists live and work while studying a remote region.', 'एक आधार जहाँ वैज्ञानिक किसी दूरस्थ क्षेत्र का अध्ययन करते हुए रहते और काम करते हैं।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000927', 'expedition', 'अभियान', 'An organised journey by a team to carry out research in a particular place.', 'किसी विशेष स्थान पर अनुसंधान के लिए टीम की संगठित यात्रा।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000928', 'paleoclimate', 'पुराजलवायु', 'The climate of the distant past, studied using clues like ice cores and sediments.', 'सुदूर अतीत की जलवायु, जिसका अध्ययन हिम कोर और तलछट जैसे सुरागों से होता है।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000929', 'sediment core', 'तलछट कोर', 'A tube-shaped sample of mud or sand taken from a lake or sea floor.', 'झील या समुद्र तल से ली गई कीचड़ या रेत का नली के आकार का नमूना।') on conflict do nothing;
insert into public.glossary (id, term, term_hi, meaning_en, meaning_hi) values ('00000000-0000-4000-a000-000000000930', 'snowline', 'हिम रेखा', 'The height above which snow stays on the ground all year.', 'वह ऊँचाई जिसके ऊपर साल भर ज़मीन पर बर्फ रहती है।') on conflict do nothing;
